select public.import_course($json$ {"slug":"english-b1-b2","title":"English B1 → B2: 16-Week Preparation","subtitle":"16-week blended B2 preparation course (~63 hours full, 55 hours minimum) with 15-minute daily app sessions, Saturday writing (30 min), two weekly live lessons, and 4 checkpoints.","description":"A structured 16-week B1 to B2 preparation pathway built on output before progress. Every week follows a 7-day rotation — vocabulary, grammar (1 main point + 1 light point), listening, reading, required Friday speaking, required Saturday writing, and Sunday review — paired with two weekly live lessons (60 and 55 minutes) and four milestone checkpoints. This course provides focused B2 preparation rather than a guarantee of a B2 exam result.","cefr_from":"B1","cefr_to":"B2","total_hours":63,"min_hours":55,"duration_weeks":16,"weekly_hours":4,"daily_minutes_min":15,"daily_minutes_max":30,"live_lessons_per_week":{"count":2,"minutes":[60,55]},"positioning":"Focused B2 preparation (~63 hours full / 55 hours minimum across 16 weeks), not a guarantee of a B2 result.","outcomes":["Narrate past experiences, contrast habits, and handle real-life social interaction accurately","Understand 2–4 minute multi-accent listening tracks and 150–350 word articles at B2 pace","Deliver structured recorded speaking up to 3 minutes, culminating in B2 position statements","Plan, draft, and revise 120–220 word reports, articles, and essays with controlled error patterns","Consolidate B1 basics through the Grammar Clinic and finish with a personalised Week 16 error-log review"],"daily_flow":[{"day":"Mon","step":1,"kind":"vocabulary","label":"Vocabulary","minutes":15,"requirement":"optional","description":"Learn 8–10 new topic items with British English audio, collocations, and word families."},{"day":"Tue","step":2,"kind":"grammar","label":"Grammar","minutes":15,"requirement":"optional","description":"Practise 1 main grammar point plus 1 light grammar point (Week 16 uses your personal error log)."},{"day":"Wed","step":3,"kind":"listening","label":"Listening","minutes":15,"requirement":"either_wed_thu","description":"Complete one 2–4 minute multi-accent audio track with comprehension questions (at least 1 of Wed/Thu required weekly; listening in ≥12/16 weeks)."},{"day":"Thu","step":4,"kind":"reading","label":"Reading","minutes":15,"requirement":"either_wed_thu","description":"Read one 150–350 word B1→B2 text with comprehension checks (at least 1 of Wed/Thu required weekly; reading in ≥12/16 weeks)."},{"day":"Fri","step":5,"kind":"speaking","label":"Speaking","minutes":15,"requirement":"required","description":"Required recorded speaking task scaling from 60–90s to 3-minute B2 position statements, plus shadowing self-check."},{"day":"Sat","step":6,"kind":"writing","label":"Writing","minutes":30,"requirement":"required","description":"Required 30-minute writing task scaling from 120–150 words to 200–220 words with structured error feedback."},{"day":"Sun","step":7,"kind":"review","label":"Review","minutes":15,"requirement":"optional","description":"Review the week's spaced-repetition vocabulary cards and personal mistake log."}]} $json$::jsonb) as course_id;

